import {coachingFor,muscleColors} from './catalog.js';
export const dateKey=(date=new Date())=>{const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export function streak(state){const days=new Set(state.checkins||[]);let count=0;const d=new Date();if(!days.has(dateKey(d)))d.setDate(d.getDate()-1);while(days.has(dateKey(d))){count++;d.setDate(d.getDate()-1);}return count;}
export function motivation(state){const days=streak(state),xp=(state.checkins?.length||0)*10+state.history.length*50;return `<section class="motivation-bar"><div class="flame" aria-hidden="true">🔥</div><div><span class="eyebrow">KENDİ RİTMİNDE, HER GÜN</span><h3>${days>1?days+' gündür kendine zaman ayırıyorsun.':'Bugün burada olman bile bir başlangıç.'}</h3><p>Dinlenme günlerinde de uğra. Serin giriş günlerini sayar; her gün antrenman yapman gerekmez.</p></div><div class="xp-pill">${xp} XP <small>Seviye ${Math.floor(xp/250)+1}</small></div></section>`;}
export function coachingMarkup(e){const c=coachingFor(e);return `<div class="coaching-grid"><div><span>◷ TEMPO</span><strong>${c.tempo}</strong></div><div><span>↗ BAŞLANGIÇ</span><strong>${e.category==='strength'?'2 set · Kontrollü yük':'Rahat tempoyla başla'}</strong></div></div><details class="guide-detail" open><summary>Nefes ve hareket kontrolü</summary><p>${c.breathing}</p></details><details class="guide-detail"><summary>Hangi hatalar sakatlık riskini artırır?</summary><p>${c.risk}</p><p><b>Bu harekette:</b> ${e.tip}</p><p>Bu açıklama risk farkındalığı içindir; bir ağrının nedenini teşhis etmez.</p></details><details class="guide-detail"><summary>Zor gelirse nasıl kolaylaştırırım?</summary><p>${c.easier}</p></details><details class="guide-detail"><summary>Bir sonraki seansa nasıl ilerlerim?</summary><p>${c.progress}</p></details><div class="pain-note"><strong>Kas yorgunluğu ile keskin ağrıyı ayır.</strong><p>Keskin veya giderek artan eklem ağrısı, uyuşma, ani şişlik ya da belirgin güç kaybında hareketi bırak. Mevcut sakatlığını bir uygulama rehberiyle tedavi etmeye çalışma. Göğüs ağrısı, bayılma veya ciddi nefes darlığında acil tıbbi yardım al.</p></div>`;}
export function learningMarkup(state){return `<section class="learning-card"><div><span class="eyebrow">SADECE PLAN DEĞİL, BİR YÖNTEM</span><h2>Ne yaptığını bil.<br>Gelişimini görünür kıl.</h2><p>Kasını seç, doğru hareketi öğren, yaptığın seti kaydet. Her seansın bir sonraki için referans olsun.</p><button class="primary" data-action="learning">Gelişim rehberini aç ↗</button></div><div class="learning-steps"><div><b>01</b><span>Öğren<small>Video + teknik + riskler</small></span></div><div><b>02</b><span>Uygula<small>Set, tekrar ve dinlenme</small></span></div><div><b>03</b><span>Karşılaştır<small>Kendi geçmişinle ilerle</small></span></div></div></section>`;}
export function learningGuide(){return `<span class="eyebrow">Fitness Copilot İLE GELİŞİM</span><h2 style="margin:12px 0">Önce düzen. Sonra daha fazlası.</h2><div class="steps-list"><div class="step-item"><b>1</b><div>İlk hafta: hareketi öğren.<small>Rahat yük seç. 5–10 dakika ısın, her harekette kontrollü bir deneme seti yap. Son tekrarlarında da tekniğin korunmalı.</small></div></div><div class="step-item"><b>2</b><div>İkinci hafta: tutarlı ol.<small>Aynı hareketlerde set, tekrar ve yükünü kaydet. Daha çok hareket eklemekten önce mevcut planına devam et.</small></div></div><div class="step-item"><b>3</b><div>Kontrolün iyiyse küçük artış yap.<small>Tekrar aralığının üst sınırını iki seansta ağrısız ve kontrollü tamamladıysan en küçük yük artışını dene. Aynı anda her değişkeni artırma.</small></div></div><div class="step-item"><b>4</b><div>Toparlanmayı takip et.<small>Uyku, günlük enerji ve ağrısız hareket de gelişimin parçasıdır. Sürekli yorgunsan aynı yükte kal veya hacmi azalt; gerekirse uzmana danış.</small></div></div></div><div class="tip">XP ve rozetler düzeni görünür kılar; kas gelişimini ölçmez. Tartı değişimi veya belirli bir vücut görünümü garanti edilmez.</div>`;}
export function achievementMarkup(state){return `<div class="achievement-grid">${[[1,'İlk Adım','İlk antrenman'],[5,'Ritim Bulucu','5 antrenman'],[12,'İstikrar','12 antrenman']].map(([n,title,sub])=>`<div class="achievement ${state.history.length>=n?'unlocked':''}"><span>${state.history.length>=n?'✦':'◇'}</span><strong>${title}</strong><small>${sub} · ${state.history.length>=n?'Kazanıldı':Math.min(n,state.history.length)+' / '+n}</small></div>`).join('')}</div>`;}
export function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const p=document.createElement('i');p.style.cssText=`--x:${Math.random()*100}vw;--delay:${Math.random()*.3}s;--color:${Object.values(muscleColors)[i%11]};--rotation:${Math.random()*720}deg`;layer.appendChild(p);}document.body.appendChild(layer);setTimeout(()=>layer.remove(),2200);}
